import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";import"./chunks/assets.JoaDwx61.js";var i=JSON.parse(`{"title":"Installing Visual Studio Code and AL Extensions","description":"","frontmatter":{},"headers":[],"relativePath":"installation-and-setup/install-vs-code-and-al-extensions.md","filePath":"installation-and-setup/install-vs-code-and-al-extensions.md"}`),a={name:`installation-and-setup/install-vs-code-and-al-extensions.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="installing-visual-studio-code-and-al-extensions" tabindex="-1">Installing Visual Studio Code and AL Extensions <a class="header-anchor" href="#installing-visual-studio-code-and-al-extensions" aria-label="Permalink to “Installing Visual Studio Code and AL Extensions”">​</a></h1><p>Visual Studio Code (VS Code) is the code editor we&#39;ll use to develop extensions for Microsoft Dynamics 365 Business Central using <strong>AL (Application Language)</strong>.</p><h2 id="step-1-download-and-install-vs-code" tabindex="-1">Step 1: Download and Install VS Code <a class="header-anchor" href="#step-1-download-and-install-vs-code" aria-label="Permalink to “Step 1: Download and Install VS Code”">​</a></h2><ol><li>Visit the official <a href="https://code.visualstudio.com/download" target="_blank" rel="noreferrer">Visual Studio Code download page</a>.</li><li>Download the installer for Windows.</li><li>Run the installer and follow the installation instructions.</li></ol><h2 id="step-2-install-the-al-language-extension" tabindex="-1">Step 2: Install the AL Language Extension <a class="header-anchor" href="#step-2-install-the-al-language-extension" aria-label="Permalink to “Step 2: Install the AL Language Extension”">​</a></h2><ol><li>Open VS Code.</li><li>Click the <strong>Extensions</strong> icon in the Activity Bar on the left, or press <code>Ctrl + Shift + X</code>.</li><li>Search for <code>AL Language</code>.</li><li>Install <strong>AL Language</strong>, published by Microsoft.</li></ol><p><img src="/al-language-extension.png" alt="AL Language Extension" width="1575" height="706"></p><p>This extension provides the core tools for Business Central development, including AL syntax support, IntelliSense, code diagnostics, and commands for downloading symbols, building packages, and publishing extensions.</p><h2 id="step-3-install-additional-al-development-extensions" tabindex="-1">Step 3: Install Additional AL Development Extensions <a class="header-anchor" href="#step-3-install-additional-al-development-extensions" aria-label="Permalink to “Step 3: Install Additional AL Development Extensions”">​</a></h2><h3 id="az-al-dev-tools-al-code-outline" tabindex="-1">AZ AL Dev Tools / AL Code Outline <a class="header-anchor" href="#az-al-dev-tools-al-code-outline" aria-label="Permalink to “AZ AL Dev Tools / AL Code Outline”">​</a></h3><p>Search for <strong>AZ AL Dev Tools/AL Code Outline</strong> in the Extensions Marketplace and install it.</p><p><img src="/az-al-dev-tools-extension.png" alt="AZ AL Dev Tools Extension" width="1426" height="678"></p><p>This extension provides additional productivity tools for AL development, including code navigation and outlining features that make it easier to explore objects and move around large AL files.</p><p>It complements Microsoft&#39;s official AL extension rather than replacing it.</p><h3 id="waldo-s-al-language-extension" tabindex="-1">Waldo&#39;s AL Language Extension <a class="header-anchor" href="#waldo-s-al-language-extension" aria-label="Permalink to “Waldo&#39;s AL Language Extension”">​</a></h3><p>Search for <strong>Waldo&#39;s AL Language Extension</strong> and install it.</p><p><img src="/waldos-crs-al-language-extension.png" alt="Waldo&#39;s CRS AL Language Extension" width="1438" height="618"></p><p>This extension provides additional productivity features for AL developers, helping streamline common development tasks and improve the development workflow.</p><blockquote><p><strong>Note:</strong> These additional extensions are optional. Start with Microsoft&#39;s official AL Language extension, then add third-party tools as needed. Review each extension&#39;s documentation and compatibility with your VS Code and AL versions before relying on it.</p></blockquote>`,19)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};